// ------------------------------------------------------------
// Конфигурация
// ------------------------------------------------------------
const NUMERIC_FIELDS = [
  'Calories', 'Proteins', 'Carbs', 'Fats',
  'Магний', 'Витамин D', 'Омега-3 (EPA/DHA)', 'Селен', 'Йод',
  'Калий', 'Железо', 'Кальций', 'Витамин B12', 'Витамин К',
  'Витамин Е', 'Цинк'
];

// ------------------------------------------------------------
// Вспомогательные функции
// ------------------------------------------------------------

/**
 * Безопасное преобразование строки в число
 */
function toNumber(value) {
  if (value === null || value === undefined || value === '') return 0;
  const num = parseFloat(value);
  return isNaN(num) ? 0 : num;
}

/**
 * Парсинг даты с учётом временной зоны и сдвига ±2 часа
 * Если время < 2:00, считаем предыдущим днём
 */
function parseDateWithShift(dateStr) {
  if (!dateStr) return null;

  let date;
  if (dateStr instanceof Date) {
    date = new Date(dateStr);
  } else {
    const str = String(dateStr).trim();
    const isoMatch = str.match(/^(\d{4}-\d{2}-\d{2})[T ]/);
    if (isoMatch) {
      date = new Date(str);
    } else {
      const ymdMatch = str.match(/^(\d{4})-(\d{2})-(\d{2})$/);
      if (ymdMatch) {
        date = new Date(parseInt(ymdMatch[1]), parseInt(ymdMatch[2]) - 1, parseInt(ymdMatch[3]), 12, 0, 0);
      } else {
        const dmyMatch = str.match(/^(\d{2})\.(\d{2})\.(\d{4})$/);
        if (dmyMatch) {
          date = new Date(parseInt(dmyMatch[3]), parseInt(dmyMatch[2]) - 1, parseInt(dmyMatch[1]), 12, 0, 0);
        } else {
          date = new Date(str);
        }
      }
    }
  }

  if (isNaN(date.getTime())) return null;

  const hours = date.getHours();
  if (hours < 2) {
    date.setDate(date.getDate() - 1);
  }
  return date;
}

/**
 * Форматирование даты в YYYY-MM-DD
 */
function formatDate(date) {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
}

/**
 * Получить самую позднюю дату (без учёта сдвига, для определения окна)
 */
function getMaxDate(rows) {
  let maxDate = null;
  rows.forEach(row => {
    const date = parseDateWithShift(row.Date);
    if (date && (!maxDate || date > maxDate)) {
      maxDate = date;
    }
  });
  return maxDate;
}

/**
 * Проверить, попадает ли дата в окно последних N дней (не включая maxDate)
 */
function isWithinLastNDays(date, maxDate, nDays) {
  if (!date || !maxDate) return false;
  if (date >= maxDate) return false;
  const diffTime = maxDate - date;
  const diffDays = diffTime / (1000 * 60 * 60 * 24);
  return diffDays > 0 && diffDays <= nDays;
}

/**
 * Расчёт коэффициента вариации (в процентах)
 */
function calcVariation(values) {
  if (values.length < 2) return null;
  const mean = values.reduce((sum, v) => sum + v, 0) / values.length;
  const squaredDiffs = values.map(v => Math.pow(v - mean, 2));
  const variance = squaredDiffs.reduce((sum, v) => sum + v, 0) / values.length;
  const stdDev = Math.sqrt(variance);
  return (stdDev / mean) * 100;
}

// ------------------------------------------------------------
// Основная логика
// ------------------------------------------------------------

// 1. Получить все строки из входа
const allRows = $input.all().map(item => item.json);

if (allRows.length === 0) {
  return [{ json: { error: 'Нет данных для анализа' } }];
}

// 2. Найти максимальную дату
const maxDate = getMaxDate(allRows);
if (!maxDate) {
  return [{ json: { error: 'Не удалось определить даты в данных' } }];
}

// 3. Отфильтровать записи за последние 7 дней ДО максимальной даты
const filteredRows = allRows.filter(row => {
  const date = parseDateWithShift(row.Date);
  if (!date) return false;
  if (formatDate(date) === formatDate(maxDate)) return false;
  return isWithinLastNDays(date, maxDate, 7);
});

// 4. Группировка по пользователям и дням
const userData = {};

filteredRows.forEach(row => {
  const userId = row.User_ID;
  if (!userId) return;

  const date = parseDateWithShift(row.Date);
  if (!date) return;
  const dateStr = formatDate(date);

  if (!userData[userId]) {
    userData[userId] = { days: {} };
  }

  if (!userData[userId].days[dateStr]) {
    userData[userId].days[dateStr] = {
      sums: {}
    };
    NUMERIC_FIELDS.forEach(field => {
      userData[userId].days[dateStr].sums[field] = 0;
    });
  }

  const dayEntry = userData[userId].days[dateStr];
  NUMERIC_FIELDS.forEach(field => {
    dayEntry.sums[field] += toNumber(row[field]);
  });
});

// 5. Для каждого пользователя рассчитать средние за день
const outputRows = [];

Object.entries(userData).forEach(([userId, data]) => {
  const days = Object.keys(data.days).sort();
  const daysCount = days.length;

  if (daysCount === 0) return;

  const dailyValues = {};
  NUMERIC_FIELDS.forEach(field => { dailyValues[field] = []; });

  days.forEach(dateStr => {
    const dayData = data.days[dateStr];
    NUMERIC_FIELDS.forEach(field => {
      dailyValues[field].push(dayData.sums[field]);
    });
  });

  // Сумма за период (только для расчёта среднего)
  const totals = {};
  NUMERIC_FIELDS.forEach(field => {
    totals[field] = dailyValues[field].reduce((sum, v) => sum + v, 0);
  });

  // Среднее за день
  const averages = {};
  NUMERIC_FIELDS.forEach(field => {
    averages[field] = daysCount > 0 ? totals[field] / daysCount : 0;
  });

  // Стабильность по калориям
  const calorieValues = dailyValues['Calories'];
  const variation = calcVariation(calorieValues);
  const stability = variation !== null ? Math.max(0, 100 - variation).toFixed(1) : null;

  // Формируем одну строку
  const outputRow = {
    'User_ID': userId,
    'Date': formatDate(maxDate),
    'Дней с данными': daysCount,
    'Стабильность питания, %': stability ? `${stability}%` : 'недостаточно данных'
  };

  NUMERIC_FIELDS.forEach(field => {
    outputRow[field] = Number(averages[field].toFixed(1));
  });

  outputRows.push(outputRow);
});

return outputRows.map(row => ({ json: row }));

